/*
 * A040659  Continued fraction for sqrt(686).
 * https://oeis.org/A040659
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, easy
 * Formula:   a(n) = continued fraction coefficient of sqrt(686) with
 *            a(0)=floor(sqrt(686))=26, and the periodic part generated by the
 *            standard continued‑fraction algorithm for sqrt(D)
 * Range:     u8 n <= 0, u16 n <= 83, u32 n <= 83, u64 n <= 83, u128 n <= 83,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

static const seq_t D = (seq_t)686;

seq_t a(idx_t n)
{
    /* The integer part (offset 0). */
    static seq_t const first = (seq_t)26;

    /* Cache for the periodic part, computed only once. */
    static seq_t *period   = NULL;
    static idx_t period_len = 0;   /* length of the period (number of terms
                                     after the integer part). */

    if (n == 0u)
        return first;           /* a(0) */

    /* Compute the period on first use. */
    if (!period) {
        /* Use the standard continued fraction algorithm for sqrt(D). */
        seq_t m      = (seq_t)0;
        seq_t d      = (seq_t)1;
        seq_t a0     = first;
        seq_t two_a0 = (seq_t)2 * a0;   /* Term that signals end of period */

        /* Start with a reasonable capacity. */
        size_t cap = 64;
        period = (seq_t*)malloc(cap * sizeof(seq_t));
        if (!period) abort();

        size_t len = 0;
        while (1) {
            /* m_{k+1} = d * a_k - m_k */
            m = d * a0 - m;

            /* d_{k+1} = (D - m_{k+1}^2) / d_k */
            d = (D - m * m) / d;

            /* a_{k+1} = floor((a_0 + m_{k+1}) / d_{k+1}) */
            a0 = (first + m) / d;

            /* Grow the array if needed. */
            if (len >= cap) {
                cap <<= 1;
                period = (seq_t*)realloc(period, cap * sizeof(seq_t));
                if (!period) abort();
            }

            period[len++] = a0;    /* Store the new coefficient */

            if (a0 == two_a0)      /* Period ends when a_k == 2*a0_initial */
                break;
        }
        period_len = (idx_t)len;
    }

    /* Return the requested term using the periodicity. */
    idx_t offset = (n - 1u) % period_len;
    return period[(size_t)offset];
}
